import html as h
from fastapi import Form
from fastapi.responses import HTMLResponse
import app as core

app = core.app
app.title = 'PhishingGuard'
app.version = '5.0'
# Replace v4 homepage/form handlers while retaining the tested scanner, API and health routes.
app.router.routes[:] = [r for r in app.router.routes if not (getattr(r,'path',None)=='/' and ({'GET','POST'} & set(getattr(r,'methods',[]) or [])))]

CSS='''
:root{--bg:#05070d;--panel:#0b101b;--panel2:#101827;--ink:#f5f8ff;--muted:#98a6ba;--line:#202b3d;--cyan:#56e6d8;--blue:#5e8cff;--lime:#a8f06a;--red:#ff6279;--amber:#ffc95c}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 80% 5%,#13243c 0,transparent 27%),radial-gradient(circle at 10% 35%,#102a2c 0,transparent 22%),var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif}.shell{max-width:1220px;margin:auto;padding:0 24px}.nav{height:78px;display:flex;align-items:center;justify-content:space-between;gap:22px;border-bottom:1px solid rgba(255,255,255,.06)}.brand{display:flex;align-items:center;gap:11px;font-weight:900;font-size:19px;letter-spacing:-.03em}.shield{width:37px;height:41px;display:grid;place-items:center;background:linear-gradient(145deg,var(--cyan),var(--blue));clip-path:polygon(50% 0,95% 18%,88% 72%,50% 100%,12% 72%,5% 18%);color:#041018;font-size:18px}.links{display:flex;align-items:center;gap:28px}.links a,.foot a{color:#aab6c7;text-decoration:none;font-size:13px}.links a:hover{color:#fff}.navcta,.primary{background:var(--cyan);color:#04110f!important;padding:11px 17px;border-radius:9px;font-weight:850!important}.hero{min-height:650px;display:grid;grid-template-columns:1.05fr .95fr;align-items:center;gap:55px;padding:70px 0 55px}.pill{display:inline-flex;align-items:center;gap:8px;border:1px solid #25433f;background:#0b1c1b;color:#a8e9df;border-radius:999px;padding:8px 12px;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.12em}.pulse{width:7px;height:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 12px var(--lime)}h1{font-size:clamp(46px,6vw,76px);line-height:.98;letter-spacing:-.058em;margin:22px 0 20px;max-width:720px}.gradient{background:linear-gradient(90deg,#fff,var(--cyan));-webkit-background-clip:text;color:transparent}.lead{font-size:18px;line-height:1.65;color:#a7b4c6;max-width:650px}.scan{display:flex;margin-top:30px;padding:7px;background:#090e17;border:1px solid #2a3649;border-radius:13px;box-shadow:0 20px 60px rgba(0,0,0,.3)}.scan input{flex:1;min-width:0;border:0;outline:0;background:transparent;color:white;padding:15px;font-size:15px}.scan button{border:0;background:linear-gradient(135deg,var(--cyan),#7ae7b5);font-weight:900;border-radius:9px;padding:0 22px;cursor:pointer}.micro{display:flex;gap:18px;flex-wrap:wrap;margin-top:14px;color:#73839a;font-size:11px}.mock{position:relative;background:linear-gradient(145deg,#0e1725,#090e17);border:1px solid #28354a;border-radius:22px;padding:20px;box-shadow:0 35px 90px #0009}.mock:before{content:'';position:absolute;inset:-1px;border-radius:22px;background:linear-gradient(135deg,#56e6d833,transparent 35%,#5e8cff22);z-index:-1}.mocktop{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #202b3b;padding-bottom:14px}.dots{display:flex;gap:5px}.dots i{width:7px;height:7px;background:#445066;border-radius:50%}.status{font-size:10px;color:#9bd9cd}.risk{display:grid;grid-template-columns:140px 1fr;gap:20px;align-items:center;padding:25px 0}.ring{width:130px;height:130px;border-radius:50%;background:conic-gradient(var(--amber) 72%,#1a2638 0);display:grid;place-items:center}.ring:after{content:'72';width:104px;height:104px;border-radius:50%;background:#0b111d;display:grid;place-items:center;font-size:35px;font-weight:950}.risk h3{font-size:24px;margin:6px 0;color:var(--amber)}.risk p{color:#8595aa;font-size:12px;line-height:1.5}.minirow{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.mini{background:#0b1421;border:1px solid #1c2a3c;padding:12px;border-radius:11px}.mini b{display:block;font-size:18px}.mini span{font-size:9px;color:#71839a;text-transform:uppercase}.section{padding:90px 0}.sectionhead{max-width:720px;margin-bottom:38px}.eyebrow{color:var(--cyan);font-size:11px;font-weight:900;letter-spacing:.15em;text-transform:uppercase}.section h2{font-size:clamp(34px,4vw,52px);letter-spacing:-.045em;margin:10px 0 14px}.sectionhead p{color:#94a4b8;line-height:1.7}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);border-radius:18px;overflow:hidden;background:#0a101a}.stat{padding:30px;border-right:1px solid var(--line)}.stat:last-child{border:0}.stat b{font-size:32px}.stat span{display:block;color:#7f8fa4;font-size:11px;margin-top:5px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{background:linear-gradient(145deg,#0c1421,#090e17);border:1px solid var(--line);border-radius:17px;padding:25px;min-height:205px}.ico{width:42px;height:42px;border-radius:10px;background:#102a2c;border:1px solid #24504d;display:grid;place-items:center;color:var(--cyan);font-weight:900}.card h3{margin:19px 0 9px}.card p{color:#8999ae;font-size:13px;line-height:1.65}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.step{position:relative;padding:24px;background:#0a111c;border:1px solid var(--line);border-radius:15px}.num{font-size:11px;color:var(--cyan);font-weight:900}.step h3{font-size:16px}.step p{font-size:12px;color:#8292a7;line-height:1.55}.contact{display:grid;grid-template-columns:1fr 1fr;gap:35px;background:linear-gradient(135deg,#0d1b27,#0a111b);border:1px solid #26364a;border-radius:24px;padding:45px}.contact p{color:#94a4b7;line-height:1.7}.contactbox{display:grid;gap:10px}.contactbox div{padding:14px 16px;border:1px solid #26364a;background:#09101a;border-radius:10px;color:#aab7c8;font-size:13px}.foot{border-top:1px solid #1a2432;padding:35px 0 45px;display:flex;justify-content:space-between;gap:30px;color:#66778e;font-size:11px}.results{padding:35px 0 75px}.resultgrid{display:grid;grid-template-columns:.72fr 1.28fr;gap:15px}.resultcard{background:#0b111c;border:1px solid #253146;border-radius:18px;padding:25px}.score{font-size:58px;font-weight:950;letter-spacing:-.06em}.LOW{color:var(--lime)}.MEDIUM{color:var(--amber)}.HIGH,.CRITICAL{color:var(--red)}.reason{padding:11px 0;border-bottom:1px solid #1b2636;color:#b8c5d4;font-size:13px}.details{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:15px}.detail{padding:13px;background:#0a1421;border:1px solid #1d2b3e;border-radius:10px}.detail b{display:block;font-size:15px}.detail span{font-size:9px;color:#77889e;text-transform:uppercase}.warning{margin-top:15px;padding:15px;border-left:3px solid var(--cyan);background:#0b1b22;color:#b8cbd1;font-size:12px;line-height:1.6}.error{margin:30px 0;padding:18px;border:1px solid #5c2832;background:#211015;border-radius:12px;color:#ffc0ca}@media(max-width:900px){.links a:not(.navcta){display:none}.hero{grid-template-columns:1fr;padding-top:50px}.mock{max-width:600px}.cards,.steps{grid-template-columns:1fr 1fr}.stats{grid-template-columns:1fr 1fr}.stat{border-bottom:1px solid var(--line)}.contact,.resultgrid{grid-template-columns:1fr}}@media(max-width:560px){.shell{padding:0 16px}.hero{gap:35px}.scan{display:block}.scan button{width:100%;height:48px}.cards,.steps,.stats,.minirow,.details{grid-template-columns:1fr}.contact{padding:27px}.foot{display:block}.foot div{margin-bottom:12px}}
'''

def esc(x): return h.escape(str(x if x is not None else '—'))
def layout(body):
    return f'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="PhishingGuard AI-powered phishing risk analysis and cyber threat intelligence research platform"><title>PhishingGuard — AI Phishing Detection</title><style>{CSS}</style></head><body><div class="shell"><nav class="nav"><div class="brand"><div class="shield">✓</div>PhishingGuard</div><div class="links"><a href="#scanner">Scanner</a><a href="#technology">Technology</a><a href="#how">How it works</a><a href="#about">About</a><a href="#contact">Contact</a><a class="navcta" href="#scanner">Scan a URL</a></div></nav>{body}<footer class="foot"><div><b style="color:#dce6f3">PhishingGuard</b><br>AI-powered phishing risk analysis.</div><div>Cybersecurity research prototype · University of West London · © 2026 PhishingGuard</div></footer></div></body></html>'''

def homepage(result=None,error=None,url=''):
    hero=f'''<main><section class="hero" id="scanner"><div><div class="pill"><i class="pulse"></i> AI-powered cyber defence</div><h1>Know the risk <span class="gradient">before you click.</span></h1><p class="lead">PhishingGuard combines machine learning, URL intelligence, live website inspection and TLS/DNS signals to produce an explainable phishing-risk assessment in seconds.</p><form class="scan" method="post"><input name="url" value="{esc(url)}" placeholder="Enter a website URL — example.com" required><button type="submit">Analyse threat →</button></form><div class="micro"><span>✓ 4 analysis layers</span><span>✓ Explainable results</span><span>✓ Live website inspection</span><span>✓ No account required</span></div></div><div class="mock"><div class="mocktop"><b>Threat analysis</b><div class="dots"><i></i><i></i><i></i></div><span class="status">● ENGINE ONLINE</span></div><div class="risk"><div class="ring"></div><div><small style="color:#71839a">EXAMPLE RISK INDICATOR</small><h3>HIGH RISK</h3><p>Multiple signals require verification before credentials or payment information are entered.</p></div></div><div class="minirow"><div class="mini"><b>86%</b><span>ML signal</span></div><div class="mini"><b>7</b><span>Indicators</span></div><div class="mini"><b>TLS</b><span>Live check</span></div></div></div></section>'''
    extra=''
    if error: extra=f'<div class="error">{esc(error)}</div>'
    if result:
        r=result; reasons=''.join(f'<div class="reason">↳ {esc(x)}</div>' for x in r['reasons'])
        extra=f'''<section class="results"><div class="sectionhead"><div class="eyebrow">Analysis complete</div><h2>Security assessment</h2><p>{esc(r['url'])}</p></div><div class="resultgrid"><div class="resultcard"><div class="eyebrow">Overall risk indicator</div><div class="score {esc(r['risk_category'])}">{esc(r['combined_risk_indicator'])}</div><h3 class="{esc(r['risk_category'])}">{esc(r['risk_category'])} RISK</h3><p style="color:#94a4b7">{esc(r['verdict'])}</p><div class="details"><div class="detail"><b>{esc(r['deep_learning_phishing_score'])}%</b><span>ML score</span></div><div class="detail"><b>{esc(r['lexical_indicator_score'])}</b><span>URL signals</span></div><div class="detail"><b>{esc(r['contextual_indicator_score'])}</b><span>Live signals</span></div></div></div><div class="resultcard"><div class="eyebrow">Explainable intelligence</div><h3>Why PhishingGuard reached this result</h3>{reasons}<div class="warning"><b>Recommended action:</b> {esc(r['recommendation'])}</div></div></div><div class="resultcard" style="margin-top:15px"><div class="eyebrow">Technical intelligence</div><div class="details"><div class="detail"><b>{esc(r['domain']['registered_domain'])}</b><span>Registered domain</span></div><div class="detail"><b>{esc(r['live']['http_status'])}</b><span>HTTP status</span></div><div class="detail"><b>{esc(r['live']['redirects'])}</b><span>Redirects</span></div><div class="detail"><b>{'Valid' if r['tls'].get('valid') else 'Check'}</b><span>TLS certificate</span></div><div class="detail"><b>{esc(r['html']['password_fields'])}</b><span>Password fields</span></div><div class="detail"><b>{esc(r['html']['external_form_actions'])}</b><span>External forms</span></div></div><div class="warning">{esc(r['notice'])}</div></div></section>'''
    marketing='''<section class="section"><div class="stats"><div class="stat"><b>4</b><span>ANALYSIS LAYERS</span></div><div class="stat"><b>20+</b><span>SECURITY INDICATORS</span></div><div class="stat"><b>Live</b><span>WEBSITE INSPECTION</span></div><div class="stat"><b>24/7</b><span>PUBLIC ACCESS</span></div></div></section><section class="section" id="technology"><div class="sectionhead"><div class="eyebrow">Detection technology</div><h2>More than a URL classifier.</h2><p>PhishingGuard correlates independent evidence so users can see both the assessment and the signals behind it.</p></div><div class="cards"><div class="card"><div class="ico">AI</div><h3>Deep-learning detection</h3><p>The trained phishing model analyses URL text and contributes the primary machine-learning signal.</p></div><div class="card"><div class="ico">URL</div><h3>URL intelligence</h3><p>Examines length, subdomains, suspicious tokens, encoding, punycode, entropy, shorteners and structural anomalies.</p></div><div class="card"><div class="ico">↗</div><h3>Live site inspection</h3><p>Checks redirects, forms, credential fields, external submissions, page wording and HTTP behaviour.</p></div><div class="card"><div class="ico">TLS</div><h3>TLS & DNS context</h3><p>Inspects certificate validity, issuer information, resolved addresses and destination-domain changes.</p></div><div class="card"><div class="ico">?</div><h3>Explainable findings</h3><p>Surfaces the concrete indicators that contributed to a Low, Medium, High or Critical assessment.</p></div><div class="card"><div class="ico">✓</div><h3>Actionable guidance</h3><p>Provides clear security recommendations designed for both everyday users and analyst demonstrations.</p></div></div></section><section class="section" id="how"><div class="sectionhead"><div class="eyebrow">How it works</div><h2>From URL to security insight.</h2></div><div class="steps"><div class="step"><div class="num">01</div><h3>Submit URL</h3><p>The destination is validated and internal/private network targets are blocked.</p></div><div class="step"><div class="num">02</div><h3>Extract signals</h3><p>ML and structural features are analysed alongside URL characteristics.</p></div><div class="step"><div class="num">03</div><h3>Inspect live site</h3><p>HTTP, redirects, page forms, TLS and DNS context are examined.</p></div><div class="step"><div class="num">04</div><h3>Explain risk</h3><p>Signals are combined into a risk indicator with reasons and recommended action.</p></div></div></section><section class="section" id="about"><div class="contact"><div><div class="eyebrow">About the research</div><h2>Built for practical cyber threat intelligence.</h2><p>PhishingGuard is a cybersecurity research artefact exploring how machine learning and live security indicators can support explainable phishing detection. The platform is designed for decision support and does not claim that any automated score can guarantee a website is safe or malicious.</p></div><div class="contactbox"><div><b>Research area</b><br>Machine Learning · Phishing Detection · CTI</div><div><b>Institution</b><br>University of West London</div><div><b>Platform</b><br>Public web-based research prototype</div></div></div></section><section class="section" id="contact"><div class="sectionhead"><div class="eyebrow">Contact & feedback</div><h2>Help improve PhishingGuard.</h2><p>Questions, research feedback or a suspicious URL to investigate? A dedicated project contact channel can be added here without exposing personal contact information publicly.</p></div></section></main>'''
    return layout(hero+extra+marketing)

@app.get('/',response_class=HTMLResponse)
def home(): return homepage()

@app.post('/',response_class=HTMLResponse)
def analyse(url:str=Form(...)):
    try: return homepage(core.scan(url),url=url)
    except Exception as e: return homepage(error=str(e),url=url)
